namespace Modular.Modules.FederationManagement.Application;
public sealed class FederationManagementValidator { static readonly HashSet<string> Belts=["White","Yellow","Green","Blue","Brown","Black"]; public IReadOnlyList<string> Validate(RegisterAthleteRequest x) { var e=new List<string>(); if(string.IsNullOrWhiteSpace(x.FullName)||x.FullName.Trim().Length<3)e.Add("نام ورزشکار نامعتبر است."); if(x.BirthDate>=DateOnly.FromDateTime(DateTime.UtcNow))e.Add("تاریخ تولد نامعتبر است."); if(string.IsNullOrWhiteSpace(x.NationalId)||x.NationalId.Trim().Length is <8 or >12)e.Add("شناسه ملی نامعتبر است."); if(x.ClubId==Guid.Empty)e.Add("باشگاه الزامی است."); if(!Belts.Contains(x.Belt))e.Add("کمربند نامعتبر است."); if(x.Rank is <1 or >10)e.Add("رتبه باید ۱ تا ۱۰ باشد."); return e; } public IReadOnlyList<string> Validate(CreateTournamentRequest x) { var e=new List<string>(); if(string.IsNullOrWhiteSpace(x.Name))e.Add("نام مسابقه الزامی است."); if(x.StartDate<DateOnly.FromDateTime(DateTime.UtcNow))e.Add("تاریخ مسابقه گذشته است."); if(string.IsNullOrWhiteSpace(x.Venue))e.Add("محل برگزاری الزامی است."); return e; } }
